mapper.select:
SELECT u.*, c.college_name
FROM sys_user u
LEFT JOIN sys_college c ON u.college_id = c.id
WHERE u.deleted = 0

    AND (u.real_name LIKE CONCAT('%',#{keyword},'%') OR u.username LIKE CONCAT('%',#{keyword},'%') OR u.phone LIKE CONCAT('%',#{keyword},'%'))


    AND u.role = #{role}


    AND u.college_id = #{collegeId}


    AND u.status = #{status}

ORDER BY u.create_time DESC
